PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS migration(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS modules(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lessons(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), module_id TEXT NOT NULL REFERENCES modules(id), title TEXT NOT NULL, summary TEXT NOT NULL, content TEXT NOT NULL CHECK(json_valid(content)), source_references TEXT NOT NULL CHECK(json_valid(source_references)));
CREATE TABLE IF NOT EXISTS concepts(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id), title TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, name TEXT NOT NULL, course_id TEXT REFERENCES courses(id), description TEXT NOT NULL DEFAULT '', sha256 TEXT NOT NULL UNIQUE, size INTEGER NOT NULL CHECK(size >= 0), storage_name TEXT NOT NULL UNIQUE, status TEXT NOT NULL, limitations TEXT NOT NULL CHECK(json_valid(limitations)), chapter TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_references(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, slide INTEGER, location TEXT NOT NULL, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS examples(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id), source_reference_id TEXT REFERENCES source_references(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exercises(id TEXT PRIMARY KEY, lesson_id TEXT NOT NULL REFERENCES lessons(id), type TEXT NOT NULL, prompt TEXT NOT NULL, answer TEXT NOT NULL, explanation TEXT NOT NULL, supplemental INTEGER NOT NULL DEFAULT 1, options TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(options)));
CREATE TABLE IF NOT EXISTS test_cases(id TEXT PRIMARY KEY, exercise_id TEXT NOT NULL REFERENCES exercises(id), input TEXT NOT NULL, expected TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), exercise_id TEXT NOT NULL REFERENCES exercises(id), answer TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct IN(0,1)), feedback TEXT NOT NULL, created_at TEXT NOT NULL, mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessments(id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id), title TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_attempts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), assessment_id TEXT NOT NULL REFERENCES assessments(id), score REAL NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress(user_id TEXT NOT NULL REFERENCES users(id), lesson_id TEXT NOT NULL REFERENCES lessons(id), code TEXT NOT NULL DEFAULT '', PRIMARY KEY(user_id, lesson_id));
CREATE TABLE IF NOT EXISTS review_schedule(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), lesson_id TEXT NOT NULL REFERENCES lessons(id), due_at TEXT NOT NULL, interval_days INTEGER NOT NULL CHECK(interval_days > 0), history TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(history)), UNIQUE(user_id,lesson_id));
CREATE TABLE IF NOT EXISTS achievements(id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_achievements(user_id TEXT NOT NULL REFERENCES users(id), achievement_id TEXT NOT NULL REFERENCES achievements(id), earned_at TEXT NOT NULL, PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS learning_sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), lesson_id TEXT REFERENCES lessons(id), seconds INTEGER NOT NULL CHECK(seconds >= 0), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS document_import_jobs(id TEXT PRIMARY KEY, document_id TEXT REFERENCES documents(id) ON DELETE SET NULL, name TEXT NOT NULL, status TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(user_id TEXT PRIMARY KEY REFERENCES users(id), value TEXT NOT NULL CHECK(json_valid(value)));
CREATE INDEX IF NOT EXISTS idx_references_document ON source_references(document_id);
CREATE INDEX IF NOT EXISTS idx_submissions_exercise ON submissions(exercise_id,created_at);
CREATE INDEX IF NOT EXISTS idx_lessons_course ON lessons(course_id);
CREATE INDEX IF NOT EXISTS idx_reviews_due ON review_schedule(due_at);
INSERT OR IGNORE INTO migration VALUES(1,datetime('now'));
